@Transactional
public void importAll(Path csv) {
    try (Stream<ProductRow> rows = reader.read(csv)) {
        rows.forEach(row -> {
            Product product = products.findByCode(row.code())
                    .orElseGet(() -> new Product(row.code()));
            product.update(row.name(), row.price());
            products.save(product);
        });
    }
}

